def __find_images_main_window() -> bool:
    """Searches for the images main window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the ro_treat.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Images.Main_Images_Window) is not None else False

