@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_images_window_open(waitTimeout: int = 15000) -> bool:
    """Reports whether the Image List window is open.

    Built on does_object_exist(), NOT find_object() (which __find_images_main_window() uses
    internally): find_object()'s missing-object fallback returns the first stray Edit control
    in the AUT rather than raising, so it can never actually report absence -- this can.

    :param int waitTimeout: Time in milliseconds to wait before reporting it absent
    :return: True or False
    :rtype: bool
    """
    return CommonActions.does_object_exist(Images.Main_Images_Window, waitTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_photos_and_diagrams_window_open(waitTimeout: int = 15000) -> bool:
    """Reports whether the Photos and Diagrams image viewer is open.

    This is the one image viewer the object map actually covers (photos_and_Diagrams_Window in
    mosaiq_images_objects.py), and it is what opening a row from the Image List brings up. Use
    this rather than diffing top-level window captions: findAllObjects({"type": "Window"}) does
    not enumerate Mosaiq's nested child windows, so a caption diff reports nothing opened even
    when a viewer is plainly on screen. The map here is a top-level Wildcard text match, the same
    shape as Main_Images_Window, which does resolve.

    :param int waitTimeout: Time in milliseconds to wait before reporting it absent
    :return: True or False
    :rtype: bool
    """
    return CommonActions.does_object_exist(Images.photos_and_Diagrams_Window, waitTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def __search_for_item_from_image_list(dateTimeValue: str, searchValue: str) -> opt[object]:
    """Finds the row in the Image List table with the string values given from the
    child objects in the Image List data panel and if found return the cell object

    :param str dateTimeValue: Date/Time string value to be searched from the ImageList table
    :param str searchValue: Any other string value in the row to be searched
    """
    image_object_list = CommonActions.get_child_objects_by_object_type(
        CommonActions.get_child_objects(Images.image_Data_Panel_Table ),
        "WindowsFormsAccessibleObject")

    list_row_item = CommonActions.get_child_object_by_value(image_object_list, dateTimeValue, searchValue) #type: ignore
    # Guard against no row matching: get_child_object_by_value() returns None in that case, and
    # feeding None to get_child_objects() reaches squishtest.object.children(None), which raises a
    # low-level error rather than reporting "no such row". This function's own -> opt[object]
    # contract says a miss comes back as None, and is_image_row_displayed() depends on that.
    if list_row_item is None:
        return None
    cell_obj = CommonActions.get_child_object_by_value(CommonActions.get_child_objects(list_row_item), searchValue)
    if cell_obj is not None:
        return cell_obj

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def __search_for_item_by_index_from_image_list(listIndex: int, searchValue: Tuple[str, ...]) -> opt[object]:
    """
    Searches the Image List table and gets a list of all the object rows that matched
    the search value(s). Returns a single object row from this list using the index
    as specified by the listIndex parameter.

    :param int listIndex: Index of the object row to return from the list of found objects
    :param str searchValue: Any search string value in the row to be searched
    """
    image_object_list = CommonActions.get_child_objects_by_object_type(
        CommonActions.get_child_objects(Images.image_Data_Panel_Table ),
        "WindowsFormsAccessibleObject")

    matched_obj_list = CommonActions.get_child_objects_by_object_value(image_object_list, *searchValue) #type: ignore
    # matched_obj_list already filtered by matched string values - now select the object using the first matching searchValue from the tuple
    cell_obj = CommonActions.get_child_object_by_value(CommonActions.get_child_objects(matched_obj_list[listIndex]), searchValue[0])
    if cell_obj is not None:
        return cell_obj

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_image_row_displayed(dateTimeValue: str, searchValue: str) -> bool:
    """Reports whether a row matching dateTimeValue/searchValue exists in the Image List.

    Check this before double_click_on_item_from_list() et al: those functions look the row up
    the same way but silently do nothing when it is not found, so a miss otherwise passes
    unnoticed instead of failing the step that depends on it.

    :param str dateTimeValue: Date/Time string value to search the Image List row for
    :param str searchValue: Any other string value in the row to search for
    :return: True or False
    :rtype: bool
    """
    return __search_for_item_from_image_list(dateTimeValue, searchValue) is not None

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_image_row_values(dateTimeValue: str, searchValue: str) -> 'list[str]':
    """Returns the text of every cell in the Image List row matching dateTimeValue/searchValue.

    __search_for_item_from_image_list() already does this row lookup privately, to find one
    cell to click; this exposes the whole row's values instead, so a test can read what Mosaiq
    recorded for a reviewed image -- reviewer, status, date/time -- rather than only click it.

    Uses the same dateTimeValue/searchValue arguments as double_click_on_item_from_list(), so
    calling both with the same values reads back the row that was opened.

    :param str dateTimeValue: Date/Time string value to search the Image List row for
    :param str searchValue: Any other string value in the row to search for
    :return: cell text values for the matching row, in the order the row exposes its children;
             empty when no row matched
    :rtype: list[str]
    """
    if not __find_images_main_window():
        return []
    image_object_list = CommonActions.get_child_objects_by_object_type(
        CommonActions.get_child_objects(Images.image_Data_Panel_Table),
        "WindowsFormsAccessibleObject")
    row_obj = CommonActions.get_child_object_by_value(image_object_list, dateTimeValue, searchValue) #type: ignore
    if row_obj is None:
        return []
    # Cells expose their text as `.value` -- the same attribute
    # __find_by_value_in_child_object_list() (behind get_child_object_by_value()) filters on --
    # not `.text`, which these WindowsFormsAccessibleObject cells do not carry.
    return [str(getattr(cell, "value", "") or "") for cell in CommonActions.get_child_objects(row_obj)]

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def double_click_on_item_from_list(dateTimeValue: str, searchValue: str) -> None:
    """Double click on the found cell object row item from the ImageList table to open.

    :param str dateTimeValue: Date/Time string value to be searched from the ImageList table
    :param str searchValue: Any other string value in the row to be searched
    """
    found_image_cell_obj = __search_for_item_from_image_list(dateTimeValue, searchValue)
    if found_image_cell_obj is not None:
        CommonActions.double_click_object(found_image_cell_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def double_click_on_item_from_list_using_index(listIndex: int, *searchValue: str) -> None:
    """Double click on the found cell object row item from the ImageList table to open.

    :param int listIndex: Index of the object row to select from the list of found objects
    :param str searchValue: A single or multiple string text value(s) in the row to be searched
    """
    found_image_cell_obj = __search_for_item_by_index_from_image_list(listIndex, searchValue)
    if found_image_cell_obj is not None:
        CommonActions.double_click_object(found_image_cell_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def single_click_on_item_from_list(dateTimeValue: str, searchValue: str) -> None:
    """Single left mouse click on the found cell object from the ImageList window.
    This function can be used to select a row from the ImageList followed by a
    function such as delete_image_from_image_list().

    :param str dateTimeValue: Date/Time string value to be searched from the ImageList table
    :param str searchValue: Any other string value in the row to be searched
    """
    found_image_cell_obj = __search_for_item_from_image_list(dateTimeValue, searchValue)
    if found_image_cell_obj is not None:
        CommonActions.left_click_object_no_move(found_image_cell_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def single_click_on_item_using_index_from_list(listIndex: int, *searchValue: str) -> None:
    """Single left mouse click on the found cell object from the ImageList window.
    This function can be used to select a row from the ImageList followed by a
    function such as delete_image_from_image_list().

    :param int listIndex: Index of the object row to select from the list of found objects
    :param str searchValue: A single or multiple string text value(s) in the row to be searched
    """
    found_image_cell_obj = __search_for_item_by_index_from_image_list(listIndex, searchValue)
    if found_image_cell_obj is not None:
        CommonActions.left_click_object_no_move(found_image_cell_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_sro_browser_button() -> None:
    """Clicks the SRO Browser toolbar button on the Image List window.

    NOT VERIFIED against a live viewer -- sRO_Browser_ToolbarItem (mosaiq_images_objects.py) was
    mapped but nothing was ever built to drive it, and whatever clinical image viewer / SRO
    Browser window it opens has no object map at all (only the separate Photos-and-Diagrams
    editor does). Callers should check for a new top-level window appearing afterwards rather
    than a specific viewer window map, since that map does not exist yet.
    """
    if __find_images_main_window():
        CommonActions.left_click_object(Images.sRO_Browser_ToolbarItem)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def close_image_and_diagram_window() -> None:
    """close images and diagram window
    """
    if __find_images_main_window():
        CommonActions.left_click_object(Images.Main_Images_Window)
        CommonActions.press_esc_key()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_type_dropdown_options_on_photo_diagram_window() -> None:
    """open the option dropdown to choose option on photo_and_diagram_window
    """
    if __find_photo_and_diagram_window():
        CommonActions.left_click_object(Images.type_dropdown)
        i=1
        while i<4:
            CommonActions.press_key_down_arrow()
            i=i+1

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_type_option_on_photo_and_diagram_window(type:str) -> None:
    """Select type from the dropdown on photo_and_diagram_window

    :param str type: option to select from dropdown
    """
    if __find_type_list_window():
        textFound = CommonActions.get_all_text_via_ocr_in_object(Images.type_option)
        option = CommonActions.get_object_by_ocr_text_in_object(Images.type_option,type)
        CommonActions.click_screen_area_object(option)

