@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_association_option_field_on_image_association_window(searchValue: str) -> None:
    """select association option, check for association window -> select Field radio button -> and click on ok button ->this openups another window
    ->select option from traetment field defination window - >  click on select button

    :param int searchValue: Text string to search for
    """
    if __find_image_association_window():
        CommonActions.left_click_object(Images.field_RadioButton)
        CommonActions.left_click_object(Images.ok_Button_association_window)
        if __find_treatment_field_definition_window():
            option = CommonActions.get_object_by_ocr_text_in_object(Images.treatment_Field_Definition_Pane,searchValue)
            CommonActions.click_screen_area_object(option)
            CommonActions.left_click_object(Images.treatment_Field_Definition_select_Button)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_association_option_site_on_image_association_window(searchValue: str) -> None:
    """select association option, check for association window -> select Site radio button -> and click on ok button
        -> select option from the treatment site definition wondow -> click on select button

    :param int searchValue: Text string to search for
    """
    if __find_image_association_window():
        CommonActions.left_click_object(Images.site_RadioButton)
        CommonActions.left_click_object(Images.ok_Button_association_window)
        if __find_prescription_Sites_Window():
            option = CommonActions.get_object_by_ocr_text_in_object(Images.prescription_Sites_list_pane,searchValue)
            CommonActions.click_screen_area_object(option)
            CommonActions.left_click_object(Images.prescription_Sites_select_Button)

